    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    # Prefix sums of nonzero cells for O(1) zero-rectangle checks
    ps = [[0] * (w + 1) for _ in range(h + 1)]
    for r in range(h):
        row_sum = 0
        for c in range(w):
            row_sum += 1 if grid[r][c] != 0 else 0
            ps[r + 1][c + 1] = ps[r][c + 1] + row_sum

    def rect_nonzero_count(r1, r2, c1, c2):
        return (
            ps[r2 + 1][c2 + 1]
            - ps[r1][c2 + 1]
            - ps[r2 + 1][c1]
            + ps[r1][c1]
        )

    def is_zero_rect(r1, r2, c1, c2):
        return rect_nonzero_count(r1, r2, c1, c2) == 0

    rects = []

    # Enumerate maximal zero rectangles by row-pair scanning
    for r1 in range(h):
        zero_cols = [True] * w
        for r2 in range(r1, h):
            for c in range(w):
                if grid[r2][c] != 0:
                    zero_cols[c] = False

            c = 0
            while c < w:
                if not zero_cols[c]:
                    c += 1
                    continue
                s = c
                while c < w and zero_cols[c]:
                    c += 1
                e = c - 1

                # Check maximality: cannot extend left/right/up/down
                up_ok = r1 > 0 and is_zero_rect(r1 - 1, r1 - 1, s, e)
                down_ok = r2 + 1 < h and is_zero_rect(r2 + 1, r2 + 1, s, e)
                left_ok = s > 0 and is_zero_rect(r1, r2, s - 1, s - 1)
                right_ok = e + 1 < w and is_zero_rect(r1, r2, e + 1, e + 1)

                if not (up_ok or down_ok or left_ok or right_ok):
                    rects.append((r1, r2, s, e))

    # Deduplicate
    rects = list(dict.fromkeys(rects))

    # Keep only substantial rectangles; these are the ones transformed in examples
    candidates = []
    for r1, r2, c1, c2 in rects:
        hh = r2 - r1 + 1
        ww = c2 - c1 + 1
        area = hh * ww
        if hh >= 2 and ww >= 2 and area >= 20:
            candidates.append((r1, r2, c1, c2))

    # Remove rectangles fully contained in a larger candidate
    filtered = []
    for i, a in enumerate(candidates):
        r1, r2, c1, c2 = a
        area_a = (r2 - r1 + 1) * (c2 - c1 + 1)
        contained = False
        for j, b in enumerate(candidates):
            if i == j:
                continue
            R1, R2, C1, C2 = b
            area_b = (R2 - R1 + 1) * (C2 - C1 + 1)
            if area_b > area_a and R1 <= r1 <= r2 <= R2 and C1 <= c1 <= c2 <= C2:
                contained = True
                break
        if not contained:
            filtered.append(a)

    # Paint:
    # - wide horizontal zero rectangles: fill all but last row
    # - tall vertical zero rectangles: fill all but last column
    # - near-square: fill entire rectangle
    for r1, r2, c1, c2 in filtered:
        hh = r2 - r1 + 1
        ww = c2 - c1 + 1

        if ww > hh and hh >= 2:
            rr2 = r2 - 1
            cc2 = c2
        elif hh > ww and ww >= 2:
            rr2 = r2
            cc2 = c2 - 1
        else:
            rr2 = r2
            cc2 = c2

        if rr2 >= r1 and cc2 >= c1:
            for r in range(r1, rr2 + 1):
                for c in range(c1, cc2 + 1):
                    out[r][c] = 3

    return out

